#include <stdio.h>
struct Point { int x; int y; };
void move_right(struct Point *point) {
 if (point != NULL) ++point->x;
}
int main(void) {
 struct Point p = {3, 4};
 move_right(&p);
 printf("%d,%d\n", p.x, p.y);
 return 0;
}

#include <stdio.h>
struct Account { int balance; };
void deposit(struct Account *account, int amount) { if (account != NULL && amount > 0) account->balance += amount; }
int main(void) { struct Account a = {100}; deposit(&a, 25); printf("%d\n", a.balance); return 0; }
